let KEV=null,NVD=null,EPSS=null,RW=null,RWHIST=null,MYCERT=null;
let NVD_BY_ID=new Map(),EPSS_BY_ID=new Map(),UNIFIED=[];
let PAGE=1,FEED_FILTER='all',FEED_LIMIT=24,KNOWN_FEED_IDS=null,VULN_PRESET='all';
let RW_FAST_POLLING=false,RW_SEEN_RECENT_IDS=null,RW_NEW_IDS=new Set(),RW_FAST_TIMER=null;
const PAGE_SIZE=50;
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=n=>Number(n||0).toLocaleString();
const safeNum=(n,d=0)=>Number.isFinite(Number(n))?Number(n):d;
const sourceReady=x=>x?.meta?.status==='ok';
function dateMs(v){const t=new Date(v).getTime();return Number.isFinite(t)?t:0}
function relTime(v){if(!v)return'Not collected';const t=dateMs(v);if(!t)return'Unknown';let s=Math.floor((Date.now()-t)/1000);if(s<0)s=0;if(s<60)return`${s}s ago`;const m=Math.floor(s/60);if(m<60)return`${m}m ago`;const h=Math.floor(m/60);if(h<48)return`${h}h ago`;return`${Math.floor(h/24)}d ago`}
function fmtDate(v){if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleString()}
function ageDays(s){if(!s)return Infinity;return(Date.now()-new Date(`${s}T00:00:00Z`).getTime())/86400000}
function withinDays(v,days){const t=dateMs(v);return !!t&&(Date.now()-t)>=-86400000&&(Date.now()-t)<=days*86400000}
function priorityLabel(s){return s>=75?'CRITICAL':s>=55?'HIGH':s>=35?'MEDIUM':'LOW'}
function ctiPriority(v){const sev=String(v.nvd?.cvss?.severity||'UNKNOWN').toUpperCase();let s=({CRITICAL:30,HIGH:24,MEDIUM:15,LOW:8,UNKNOWN:5})[sev]??5;const p=safeNum(v.epss?.epss);s+=p>=.7?35:p>=.5?32:p>=.2?28:p>=.1?24:p>=.05?20:p>=.01?14:6;if(v.ransomware)s+=25;const a=ageDays(v.dateAdded);s+=a<=7?10:a<=30?6:a<=90?3:0;s=Math.min(100,s);return{score:s,label:priorityLabel(s)}}
function buildUnified(){return(KEV?.vulnerabilities||[]).map(v=>{const x={...v,nvd:NVD_BY_ID.get(v.id)||null,epss:EPSS_BY_ID.get(v.id)||null};x.priority=ctiPriority(x);return x})}
function countBy(items,keyFn){const m=new Map();for(const x of items){const k=keyFn(x);if(!k)continue;m.set(k,(m.get(k)||0)+1)}return[...m.entries()].map(([name,count])=>({name,count})).sort((a,b)=>b.count-a.count||String(a.name).localeCompare(String(b.name)))}
function safeHttpUrl(v){try{const u=new URL(v);if(!/^https?:$/.test(u.protocol)||/\.onion$/i.test(u.hostname))return'#';return u.href}catch{return'#'}}
function safeMycertUrl(v){try{const u=new URL(v,'https://mycert.org.my');return/(^|\.)mycert\.org\.my$/i.test(u.hostname)?u.href:'#'}catch{return'#'}}
function nvdUrl(id){return`https://nvd.nist.gov/vuln/detail/${encodeURIComponent(id)}`}
function cisaUrl(){return'https://www.cisa.gov/known-exploited-vulnerabilities-catalog'}
function cisaCveUrl(id){return`${cisaUrl()}?search_api_fulltext=${encodeURIComponent(id)}`}
function epssUrl(id){return`https://api.first.org/data/v1/epss?cve=${encodeURIComponent(id)}`}
function ransomwareSourceUrl(){return safeHttpUrl(RW?.meta?.sourceUrl||'https://www.ransomware.live/')}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove('show'),1800)}

const ASEAN_MEMBERS=[
{name:'Malaysia',code:'MY',flag:'🇲🇾',aliases:['MALAYSIA','MY','MYS']},{name:'Singapore',code:'SG',flag:'🇸🇬',aliases:['SINGAPORE','SG','SGP']},{name:'Indonesia',code:'ID',flag:'🇮🇩',aliases:['INDONESIA','ID','IDN']},{name:'Thailand',code:'TH',flag:'🇹🇭',aliases:['THAILAND','TH','THA']},{name:'Philippines',code:'PH',flag:'🇵🇭',aliases:['PHILIPPINES','PHILIPPINE','PH','PHL']},{name:'Viet Nam',code:'VN',flag:'🇻🇳',aliases:['VIET NAM','VIETNAM','VN','VNM']},{name:'Brunei Darussalam',code:'BN',flag:'🇧🇳',aliases:['BRUNEI','BRUNEI DARUSSALAM','BN','BRN']},{name:'Cambodia',code:'KH',flag:'🇰🇭',aliases:['CAMBODIA','KH','KHM']},{name:'Lao PDR',code:'LA',flag:'🇱🇦',aliases:['LAOS','LAO','LAO PDR','LA','LAO']},{name:'Myanmar',code:'MM',flag:'🇲🇲',aliases:['MYANMAR','BURMA','MM','MMR']},{name:'Timor-Leste',code:'TL',flag:'🇹🇱',aliases:['TIMOR-LESTE','TIMOR LESTE','EAST TIMOR','TL','TLS']}];
const cleanCountry=v=>String(v||'').trim().toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();
function aseanMember(raw){const x=cleanCountry(raw);return ASEAN_MEMBERS.find(m=>m.aliases.some(a=>cleanCountry(a)===x))||null}
function regionalData(){const victims=ransomwareBaseVictims();const tagged=victims.map(v=>({v,member:aseanMember(v.country)})).filter(x=>x.member);const asean=tagged.map(x=>({...x.v,_member:x.member}));const malaysia=asean.filter(v=>v._member.code==='MY');const countryCounts=ASEAN_MEMBERS.map(m=>({member:m,count:asean.filter(v=>v._member.code===m.code).length}));return{victims,asean,malaysia,countryCounts,topCountry:countryCounts.slice().sort((a,b)=>b.count-a.count)[0],topGroup:countBy(asean,v=>v.group||'Unknown')[0]||null,topSector:countBy(asean,v=>v.sector||'Unspecified')[0]||null}}
function sourceStates(){const myDegraded=sourceReady(MYCERT)&&MYCERT?.meta?.lastAttemptStatus==='failed';return[
{code:'C',name:'CISA KEV',ready:sourceReady(KEV),degraded:false,collected:KEV?.meta?.collectedAt,url:cisaUrl(),desc:'Known exploited vulnerabilities and ransomware-use flag.'},
{code:'N',name:'NVD CVE API',ready:sourceReady(NVD),degraded:false,collected:NVD?.meta?.collectedAt,url:'https://nvd.nist.gov/',desc:'CVSS, descriptions, CWE and vulnerability metadata.'},
{code:'E',name:'FIRST EPSS',ready:sourceReady(EPSS),degraded:false,collected:EPSS?.meta?.collectedAt,url:'https://www.first.org/epss/',desc:'30-day exploitation probability and percentile.'},
{code:'R',name:'Ransomware OSINT',ready:sourceReady(RW),degraded:sourceReady(RW)&&RW?.meta?.feedFreshness==='stale',collected:RW?.meta?.collectedAt,url:ransomwareSourceUrl(),desc:'Public ransomware victim claims, groups and targeting.'},
{code:'MY',name:'MyCERT Malaysia',ready:sourceReady(MYCERT),degraded:myDegraded,collected:MYCERT?.meta?.collectedAt,url:'https://mycert.org.my/portal/index',desc:'Malaysia national advisories and cyber security signals.'}
]}
function posture(){const critical=UNIFIED.filter(x=>x.priority.label==='CRITICAL').length,epssHigh=safeNum(EPSS?.stats?.epssGe50),rw24=safeNum(RW?.stats?.claims24h);const score=Math.min(100,Math.round((critical/Math.max(UNIFIED.length,1))*1500+Math.min(35,epssHigh/8)+Math.min(30,rw24*2)));return{score,label:score>=75?'HEIGHTENED':score>=50?'ELEVATED':score>=25?'GUARDED':'NORMAL',critical,epssHigh,rw24}}

function switchTab(tab){document.querySelectorAll('.tab-panel').forEach(p=>p.classList.toggle('active',p.dataset.panel===tab));document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));history.replaceState(null,'',`#${tab}`);window.scrollTo({top:0,behavior:'smooth'})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-tab],[data-tab-jump]');if(b){const target=b.dataset.scrollTarget;switchTab(b.dataset.tab||b.dataset.tabJump);if(target)setTimeout(()=>$(target)?.scrollIntoView({behavior:'smooth',block:'start'}),260);return}const country=e.target.closest('[data-asean-code]');if(country){openAseanDrawer(country.dataset.aseanCode);return}const row=e.target.closest('[data-cve]');if(row&&!e.target.closest('a'))openCveDrawer(row.dataset.cve)});

function renderHeader(){const states=sourceStates(),healthy=states.filter(s=>s.ready&&!s.degraded).length,degraded=states.filter(s=>s.degraded).length,offline=states.filter(s=>!s.ready).length;const text=offline?`${healthy} LIVE · ${offline} OFFLINE`:degraded?`${healthy} LIVE · ${degraded} DEGRADED`:`${healthy} SOURCES LIVE`;$('feedStatus').textContent=text;$('liveDot').className=`status-led ${offline?'offline':degraded?'warn':''}`;$('lastRefresh').textContent=`Checked ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;if($('sourceOrbit'))$('sourceOrbit').innerHTML=states.map(s=>`<span class="orbit-source ${!s.ready?'offline':s.degraded?'degraded':''}"><i></i>${esc(s.code)} · ${!s.ready?'OFFLINE':s.degraded?'DEGRADED':'LIVE'}</span>`).join('');if($('sideHealth'))$('sideHealth').textContent=offline?'Degraded':degraded?'Attention':'Healthy';if($('sideHealthMeta'))$('sideHealthMeta').textContent=`${healthy} / ${states.length} sources operational`}
function renderPosture(){const p=posture();$('pulseScore').textContent=p.score;$('postureGauge').style.setProperty('--score',`${p.score*3.6}deg`);$('pulseLabel').textContent=`${p.label} external threat posture`;$('pulseStatus').textContent=p.label;$('pulseStatus').dataset.level=p.label.toLowerCase();$('pulseNarrative').textContent=`${fmt(p.critical)} KEVs currently rank Critical by CTI priority, ${fmt(p.epssHigh)} have EPSS ≥50%, and ${fmt(p.rw24)} ransomware claims in the loaded feed were discovered within 24 hours.`;$('priorityCriticalTop').textContent=fmt(p.critical);$('epss50Top').textContent=fmt(p.epssHigh);$('ransomware').textContent=fmt(KEV?.stats?.ransomwareRelated);const reg=regionalData();$('myClaims30Top').textContent=fmt(reg.malaysia.filter(v=>withinDays(v.discovered,30)).length)}

function topKevs(limit=5){return UNIFIED.slice().sort((a,b)=>b.priority.score-a.priority.score||safeNum(b.epss?.epss)-safeNum(a.epss?.epss)).slice(0,limit)}
function renderTopThree(){const p=posture(),reg=regionalData(),top=topKevs(1)[0],topGroup=(RW?.topGroups||[])[0]||reg.topGroup,latestMy=MYCERT?.advisories?.[0];const cards=[
{tone:'critical',idx:'01',value:top?`CTI ${top.priority.score}`:'WAITING',title:top?`${top.id} leads exploit-priority watchlist`:'Exploit-priority vulnerabilities',text:top?`${top.vendor} ${top.product}. CVSS ${top.nvd?.cvss?.score??'—'}, EPSS ${top.epss?`${(safeNum(top.epss.epss)*100).toFixed(1)}%`:'—'}${top.ransomware?', known ransomware use':''}.`:'Waiting for correlated CISA/NVD/EPSS intelligence.',source:'Open CVE detail',cve:top?.id},
{tone:'ransomware',idx:'02',value:`${fmt(p.rw24)} ≤24H`,title:'Ransomware activity',text:topGroup?`${topGroup.name||'Unknown'} leads the current loaded ranking${topGroup.count!=null?` with ${fmt(topGroup.count)} claims`:''}. Claims are OSINT signals, not confirmed incidents.`:'Waiting for ransomware intelligence.',source:'Open ransomware view',tab:'ransomware'},
{tone:'regional',idx:'03',value:`MY ${fmt(reg.malaysia.filter(v=>withinDays(v.discovered,30)).length)}`,title:'Malaysia / ASEAN watch',text:latestMy?`Latest MyCERT: ${latestMy.title}. ASEAN activity loaded: ${fmt(reg.asean.length)} claims.`:`ASEAN activity loaded: ${fmt(reg.asean.length)} claims. MyCERT collection pending.`,source:'Open regional view',tab:'regional'}
];$('topThree').innerHTML=cards.map(c=>`<article class="priority-card tone-${c.tone}" ${c.cve?`data-cve="${esc(c.cve)}"`:`data-tab-jump="${c.tab}"`}><div class="priority-top"><span class="priority-index">${c.idx}</span><span class="priority-value">${esc(c.value)}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.text)}</p><div class="priority-footer"><span>${esc(c.source)}</span><b>↗</b></div></article>`).join('')}

function buildDailyKev(days=30){const arr=[];for(let i=days-1;i>=0;i--){const d=new Date();d.setUTCHours(0,0,0,0);d.setUTCDate(d.getUTCDate()-i);arr.push({date:d.toISOString().slice(0,10),total:0,rw:0})}const map=new Map(arr.map(x=>[x.date,x]));for(const v of KEV?.vulnerabilities||[]){const x=map.get(v.dateAdded);if(x){x.total++;if(v.ransomware)x.rw++}}return arr}
function lineChartSvg(data,opts={}){const w=800,h=260,pL=38,pR=15,pT=18,pB=30,max=Math.max(1,...data.flatMap(d=>[d.total||0,d.rw||0]));const x=i=>pL+i*(w-pL-pR)/Math.max(data.length-1,1),y=v=>h-pB-(v/max)*(h-pT-pB);const pts=data.map((d,i)=>`${x(i)},${y(d.total)}`).join(' '),rw=data.map((d,i)=>`${x(i)},${y(d.rw)}`).join(' ');const area=`${pL},${h-pB} ${pts} ${x(data.length-1)},${h-pB}`;let grid='';for(let i=0;i<4;i++){const gy=pT+i*(h-pT-pB)/3;grid+=`<line x1="${pL}" y1="${gy}" x2="${w-pR}" y2="${gy}" class="chart-grid"/>`}const labels=data.map((d,i)=>i%7===0||i===data.length-1?`<text x="${x(i)}" y="${h-8}" text-anchor="middle">${d.date.slice(5)}</text>`:'').join('');return`<svg viewBox="0 0 ${w} ${h}" role="img"><defs><linearGradient id="kevArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5ce6ff" stop-opacity=".25"/><stop offset="1" stop-color="#5ce6ff" stop-opacity="0"/></linearGradient></defs>${grid}<polygon points="${area}" class="chart-area-fill"/><polyline points="${pts}" class="chart-line"/><polyline points="${rw}" class="chart-line-rw"/>${labels}</svg>`}
function renderKevTrend(){$('kevTrendChart').innerHTML=lineChartSvg(buildDailyKev(30))}

function renderRiskScatter(targetId){const items=topKevs(70).filter(v=>v.nvd?.cvss?.score!=null&&v.epss?.epss!=null),w=780,h=310,pL=44,pR=20,pT=22,pB=36,x=v=>pL+safeNum(v.nvd.cvss.score)/10*(w-pL-pR),y=v=>h-pB-safeNum(v.epss.epss)*(h-pT-pB);const grid=[0,2,4,6,8,10].map(n=>`<line x1="${pL+n/10*(w-pL-pR)}" y1="${pT}" x2="${pL+n/10*(w-pL-pR)}" y2="${h-pB}" class="chart-grid"/><text x="${pL+n/10*(w-pL-pR)}" y="${h-12}" text-anchor="middle">${n}</text>`).join('')+[0,.25,.5,.75,1].map(n=>`<line x1="${pL}" y1="${y({epss:{epss:n},nvd:{cvss:{score:0}}})}" x2="${w-pR}" y2="${y({epss:{epss:n},nvd:{cvss:{score:0}}})}" class="chart-grid"/><text x="${pL-8}" y="${y({epss:{epss:n},nvd:{cvss:{score:0}}})+3}" text-anchor="end">${Math.round(n*100)}%</text>`).join('');const points=items.map(v=>{const color=v.priority.label==='CRITICAL'?'#ff6578':v.priority.label==='HIGH'?'#f69b55':v.priority.label==='MEDIUM'?'#f4c76b':'#49e3a7',r=3+v.priority.score/30;return`<circle class="scatter-point" data-cve="${esc(v.id)}" data-tip="${esc(`${v.id}|CVSS ${v.nvd.cvss.score}|EPSS ${(safeNum(v.epss.epss)*100).toFixed(1)}%|CTI ${v.priority.score}`)}" cx="${x(v)}" cy="${y(v)}" r="${r}" fill="${color}" fill-opacity=".82"/>`}).join('');$(targetId).innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="CVSS by EPSS risk scatter">${grid}<text x="${w/2}" y="${h-1}" text-anchor="middle" class="axis-label">CVSS severity score →</text><text x="12" y="${h/2}" transform="rotate(-90 12 ${h/2})" text-anchor="middle" class="axis-label">EPSS exploitation probability →</text><text x="${w-pR-8}" y="${pT+12}" text-anchor="end" class="quadrant-label">HIGH SEVERITY · HIGH PROBABILITY</text>${points}</svg>`;bindScatterTooltips($(targetId))}
function bindScatterTooltips(root){let tip=document.querySelector('.scatter-tooltip');if(!tip){tip=document.createElement('div');tip.className='scatter-tooltip';document.body.appendChild(tip)}root.querySelectorAll('[data-tip]').forEach(n=>{n.addEventListener('mousemove',e=>{tip.innerHTML=n.dataset.tip.split('|').map((x,i)=>i?`<small>${esc(x)}</small>`:`<strong>${esc(x)}</strong>`).join('<br>');tip.style.left=`${e.clientX+14}px`;tip.style.top=`${e.clientY+14}px`;tip.classList.add('show')});n.addEventListener('mouseleave',()=>tip.classList.remove('show'))})}

function renderActivity(target='activityChart'){const data=RW?.dailyActivity||[];if(!data.length){$(target).innerHTML='<div class="empty-state">Waiting for ransomware activity…</div>';return}const normalized=data.map(d=>({date:d.date,total:safeNum(d.count),rw:0}));$(target).innerHTML=lineChartSvg(normalized);const first=safeNum(data[0]?.count),last=safeNum(data.at(-1)?.count),label=last>first?'RISING':last<first?'EASING':'STEADY';$('rwTrendLabel').textContent=label;if($('rwTrendLabel2'))$('rwTrendLabel2').textContent=label}
function renderOverviewAsean(){const r=regionalData(),max=Math.max(1,...r.countryCounts.map(x=>x.count));$('aseanGlance').innerHTML=r.countryCounts.slice().sort((a,b)=>b.count-a.count).slice(0,6).map(x=>`<button class="glance-row glance-click" data-asean-code="${esc(x.member.code)}" type="button"><span>${x.member.flag} ${esc(x.member.name)}</span><div class="glance-bar"><i style="width:${x.count/max*100}%"></i></div><b>${x.count}</b></button>`).join('')||'<div class="empty-state">No ASEAN claims in loaded feed.</div>'}

function severityOfEvent(v){const p=UNIFIED.find(x=>x.id===v.id)?.priority?.label;if(p==='CRITICAL')return'critical';if(p==='HIGH')return'high';return'medium'}
function makeFeedId(parts){return parts.filter(Boolean).join('|')}
function buildEvents(){const events=[];for(const v of (KEV?.vulnerabilities||[]).filter(v=>withinDays(v.dateAdded,45))){const u=UNIFIED.find(x=>x.id===v.id);events.push({id:makeFeedId(['cisa',v.id,v.dateAdded]),source:'CISA KEV',code:'CISA',kind:v.ransomware?'ransomware':'vulnerability',severity:severityOfEvent(v),time:v.dateAdded,dateOnly:true,title:`${v.id} added to CISA KEV`,detail:`${v.vendor} ${v.product}${v.vulnerabilityName?` · ${v.vulnerabilityName}`:''}`,badges:[v.ransomware?'Known ransomware use':null,u?`CTI ${u.priority.score}`:null].filter(Boolean),url:cisaUrl(),cve:v.id,malaysia:false})}if(sourceReady(NVD)){for(const v of (NVD.vulnerabilities||[]).filter(v=>withinDays(v.lastModified,14)).sort((a,b)=>dateMs(b.lastModified)-dateMs(a.lastModified)).slice(0,80)){const sev=String(v.cvss?.severity||'').toLowerCase()==='critical'?'critical':String(v.cvss?.severity||'').toLowerCase()==='high'?'high':'medium';events.push({id:makeFeedId(['nvd',v.id,v.lastModified]),source:'NVD CVE API',code:'NVD',kind:'vulnerability',severity:sev,time:v.lastModified,title:`${v.id} NVD record updated`,detail:`CVSS ${v.cvss?.score??'—'} · ${String(v.cvss?.severity||'UNKNOWN').toUpperCase()}${v.description?` · ${v.description.slice(0,180)}`:''}`,badges:[v.vulnStatus].filter(Boolean),url:v.sourceUrl||nvdUrl(v.id),cve:v.id,malaysia:false})}}if(sourceReady(EPSS)){const sample=(EPSS.vulnerabilities||[]).slice().sort((a,b)=>safeNum(b.epss)-safeNum(a.epss)).slice(0,35);for(const v of sample){const p=safeNum(v.epss);events.push({id:makeFeedId(['epss',v.id,EPSS.meta?.scoreDate]),source:'FIRST EPSS',code:'EPSS',kind:'exploitation',severity:p>=.5?'high':'medium',time:EPSS.meta?.collectedAt,title:`${v.id} EPSS ${(p*100).toFixed(2)}%`,detail:`Estimated exploitation probability in the next 30 days · ${(safeNum(v.percentile)*100).toFixed(1)} percentile`,badges:[p>=.5?'High exploit probability':'EPSS scored'],url:'https://www.first.org/epss/',cve:v.id,malaysia:false})}}if(sourceReady(RW)){for(const v of (RW.victims||[]).slice(0,100)){const member=aseanMember(v.country),isMY=member?.code==='MY';events.push({id:makeFeedId(['rw',v.id,v.discovered]),source:'Ransomware OSINT',code:'RW',kind:'ransomware',severity:isMY?'critical':'high',time:v.discovered,title:`Ransomware claim: ${v.victim||'Unknown victim'}`,detail:`${v.group||'Unknown group'} · ${v.country||'Unknown country'} · ${v.sector||'Unspecified sector'} · public leak-site claim`,badges:[v.group,isMY?'Malaysia':member?'ASEAN':null].filter(Boolean),url:ransomwareSourceUrl(),malaysia:isMY})}}if(sourceReady(MYCERT)){for(const a of (MYCERT.advisories||[])){const rw=/ransom/i.test(`${a.type} ${a.title}`),sev=/critical/i.test(a.severity||'')?'critical':/high/i.test(a.severity||'')?'high':'medium';events.push({id:makeFeedId(['my',a.id,a.date]),source:'MyCERT Malaysia',code:'MY',kind:rw?'ransomware':'malaysia',severity:sev,time:a.date,dateOnly:true,title:a.title||'MyCERT advisory',detail:`${a.type||'Advisory'}${a.cves?.length?` · ${a.cves.join(', ')}`:''}`,badges:['Malaysia',a.severity].filter(Boolean),url:safeMycertUrl(a.url),malaysia:true})}}return events.sort((a,b)=>dateMs(b.time)-dateMs(a.time))}
function eventTime(e){if(e.dateOnly)return e.time||'—';return relTime(e.time)}
function eventLink(e){return safeHttpUrl(e.url)==='#'?'#':safeHttpUrl(e.url)}
function renderOverviewFeed(){const events=buildEvents().slice(0,7),host=$('overviewLiveFeed');if(!host)return;host.innerHTML=events.map(e=>{const sev=e.severity==='critical'?'critical':e.severity==='high'?'high':e.severity==='medium'?'medium':'info',label=e.kind==='ransomware'?'RANSOMWARE':sev.toUpperCase();return`<a class="th-live-event sev-${sev}" href="${esc(eventLink(e))}" ${eventLink(e)==='#'?'':'target="_blank" rel="noopener"'}><span class="sev">${esc(label)}</span><div class="event-copy"><strong>${esc(e.title)}</strong><small>${esc(e.detail)}</small><span class="event-source">${esc(e.source)}</span></div><time>${esc(eventTime(e))}</time></a>`}).join('')||'<div class="empty-state">Waiting for timestamped intelligence.</div>'}

function renderUnifiedFeed(){const events=buildEvents();const previous=KNOWN_FEED_IDS;const ids=new Set(events.map(e=>e.id));if(KNOWN_FEED_IDS)KNOWN_FEED_IDS=ids;else KNOWN_FEED_IDS=ids;let filtered=events.filter(e=>FEED_FILTER==='all'||(FEED_FILTER==='critical'&&e.severity==='critical')||(FEED_FILTER==='ransomware'&&e.kind==='ransomware')||(FEED_FILTER==='malaysia'&&e.malaysia)||(FEED_FILTER==='vulnerability'&&['vulnerability','exploitation'].includes(e.kind)));const shown=filtered.slice(0,FEED_LIMIT);$('intelFeedCount').textContent=`${fmt(filtered.length)} signals · newest first`;$('unifiedIntelFeed').innerHTML=shown.map(e=>{const isNew=previous&&!previous.has(e.id),url=eventLink(e),tags=(e.badges||[]).slice(0,3).map(b=>`<span>${esc(b)}</span>`).join('');return`<article class="intel-event sev-${e.severity}" ${e.cve?`data-cve="${esc(e.cve)}"`:''}><span class="event-source">${esc(e.code)}</span><div class="event-body"><div class="event-top"><div class="event-badges"><span>${esc(e.severity.toUpperCase())}</span><span>${esc(e.kind.toUpperCase())}</span>${isNew?'<span class="new-signal">NEW</span>':''}</div><time>${esc(eventTime(e))}</time></div><h4>${esc(e.title)}</h4><p>${esc(e.detail)}</p>${tags?`<div class="event-badges" style="margin-top:7px">${tags}</div>`:''}</div>${url!=='#'?`<a class="event-link" href="${esc(url)}" target="_blank" rel="noopener" title="Open source">↗</a>`:'<span></span>'}</article>`}).join('')||'<div class="empty-state">No signals match this filter.</div>';$('feedMore').style.display=filtered.length>FEED_LIMIT?'inline-block':'none';const latest=events[0];$('tickerSource').textContent=latest?.source||'INTELLIGENCE';$('latestSignalTicker').textContent=latest?.title||'Waiting for source data…';$('feedUpdatedAt').textContent=new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});const within24=events.filter(e=>withinDays(e.time,1));$('signals24h').textContent=fmt(within24.length);$('criticalSignals').textContent=fmt(events.filter(e=>e.severity==='critical').length);$('ransomwareSignals').textContent=fmt(events.filter(e=>e.kind==='ransomware').length);$('malaysiaSignals').textContent=fmt(events.filter(e=>e.malaysia).length);$('latestSignalSource').textContent=latest?.source||'—';$('activeSourceCount').textContent=`${sourceStates().filter(s=>s.ready).length} SOURCES`;renderFreshness()}
function renderFreshness(){const thresholds={C:45,N:180,E:1800,R:45,MY:90};$('freshnessList').innerHTML=sourceStates().map(s=>{const mins=s.collected?(Date.now()-dateMs(s.collected))/60000:Infinity;const stale=mins>thresholds[s.code],bad=!s.ready,state=bad?'OFFLINE':s.degraded||stale?'CHECK':'FRESH';return`<div class="freshness-row"><div><strong>${esc(s.name)}</strong><small>${esc(s.collected?relTime(s.collected):'Not collected')}</small></div><b class="freshness-state ${bad?'bad':state==='CHECK'?'warn':''}">${state}</b></div>`}).join('')}

