function renderRanking(id,list,limit=8){const max=Math.max(1,...list.map(x=>safeNum(x.count)));$(id).innerHTML=list.slice(0,limit).map(x=>`<div class="rank-row"><div><div class="rank-head"><strong>${esc(x.name)}</strong></div><div class="rank-bar"><i style="width:${Math.max(3,safeNum(x.count)/max*100)}%"></i></div></div><b>${fmt(x.count)}</b></div>`).join('')||'<div class="empty-state">No activity data.</div>'}

