function renderSeverityAndEpss(){if(sourceReady(NVD)){const s=NVD.stats||{},c=safeNum(s.critical),h=safeNum(s.high),m=safeNum(s.medium),l=safeNum(s.low),u=safeNum(s.unknown),total=Math.max(1,c+h+m+l+u),a=c/total*360,b=a+h/total*360,cc=b+m/total*360,d=cc+l/total*360;$('severityDonut').style.setProperty('--donut',`conic-gradient(#ff6578 0 ${a}deg,#f69b55 ${a}deg ${b}deg,#f4c76b ${b}deg ${cc}deg,#49e3a7 ${cc}deg ${d}deg,#27415a ${d}deg 360deg)`);$('severityDonutTotal').textContent=fmt(c+h+m+l);$('sevCritical').textContent=fmt(c);$('sevHigh').textContent=fmt(h);$('sevMedium').textContent=fmt(m);$('sevLow').textContent=fmt(l);$('severityCoverage').textContent=`${safeNum(s.coveragePercent).toFixed(1)}% CVSS coverage`}if(sourceReady(EPSS)){const s=EPSS.stats||{},matched=safeNum(s.matched),ge50=safeNum(s.epssGe50),ge10=safeNum(s.epssGe10),ge1=safeNum(s.epssGe01),lt1=safeNum(s.epssLt01)||Math.max(0,matched-ge1);const bands=[['≥50%',ge50],['10–49.9%',Math.max(0,ge10-ge50)],['1–9.9%',Math.max(0,ge1-ge10)],['<1%',lt1]],max=Math.max(1,...bands.map(x=>x[1]));$('epssBandChart').innerHTML=bands.map(x=>`<div class="epss-band-row"><span>${x[0]}</span><div class="bar"><i style="width:${x[1]/max*100}%"></i></div><b>${fmt(x[1])}</b></div>`).join('');$('epssCoverage').textContent=`${safeNum(s.coveragePercent).toFixed(1)}%`;$('epssCoverageHint').textContent=`${fmt(matched)} KEVs scored`;$('epss10').textContent=fmt(ge10);$('epss99').textContent=fmt(s.percentileGe99);$('epssScoreDate').textContent=`Score date ${EPSS.meta?.scoreDate||'current'}`}}
function renderVendors(){const list=(KEV?.stats?.topVendors||[]).slice(0,12),max=Math.max(1,...list.map(x=>safeNum(x.count)));$('vendors').innerHTML=list.map((v,i)=>`<button class="vendor-row vendor-button" type="button" data-vendor-search="${esc(v.name)}"><div class="vendor-rank">${String(i+1).padStart(2,'0')}</div><div class="vendor-main"><div class="vendor-name"><strong>${esc(v.name)}</strong><span>${fmt(v.count)} KEVs</span></div><div class="vendor-bar"><div class="vendor-fill" style="width:${Math.max(3,safeNum(v.count)/max*100)}%"></div></div></div><i>↗</i></button>`).join('');$('vendorCount').textContent=`Top ${list.length} vendors`}
function vulnerabilityPressure(){const total=Math.max(1,UNIFIED.length),critical=UNIFIED.filter(v=>v.priority.label==='CRITICAL').length,epss50=UNIFIED.filter(v=>safeNum(v.epss?.epss)>=.5).length,ransom=UNIFIED.filter(v=>v.ransomware).length,new7=UNIFIED.filter(v=>ageDays(v.dateAdded)<=7).length;const score=Math.min(100,Math.round((critical/total)*1500+(epss50/total)*800+(ransom/total)*260+Math.min(18,new7*2.2)));return{score,label:score>=78?'HEIGHTENED':score>=58?'ELEVATED':score>=36?'GUARDED':'NORMAL',critical,epss50,ransom,new7,total}}
function renderVulnerabilityCommand(){const p=vulnerabilityPressure(),nvdCov=safeNum(NVD?.stats?.coveragePercent),epssCov=safeNum(EPSS?.stats?.coveragePercent);$('vulnPressureScore').textContent=p.score;$('vulnPressureOrb').style.setProperty('--vscore',`${p.score*3.6}deg`);$('vulnPressureLabel').textContent=`${p.label} exploit pressure`;$('vulnPressurePill').textContent=p.label;$('vulnPressurePill').dataset.level=p.label.toLowerCase();$('vulnPressureNarrative').textContent=`${fmt(p.critical)} KEVs rank Critical by CTI priority, ${fmt(p.epss50)} have EPSS ≥50%, ${fmt(p.ransom)} are associated with known ransomware use, and ${fmt(p.new7)} were added to KEV within 7 days.`;$('vulnCriticalKpi').textContent=fmt(p.critical);$('vulnHighEpssKpi').textContent=fmt(p.epss50);$('vulnRansomKpi').textContent=fmt(p.ransom);$('vulnNew7Kpi').textContent=fmt(p.new7);$('vulnCoverageKpi').textContent=`${nvdCov.toFixed(1)}%`;$('vulnEpssCoverageKpi').textContent=`${epssCov.toFixed(1)}%`;const states=sourceStates().filter(x=>['CISA KEV','NVD CVE API','FIRST EPSS'].includes(x.name));$('vulnSourceState').innerHTML=states.map(x=>`<span class="vuln-source-chip ${!x.ready?'offline':x.degraded?'degraded':''}"><i></i>${esc(x.name.replace(' CVE API',''))}</span>`).join('');const watch=topKevs(6);$('vulnWatchlist').innerHTML=watch.map((v,i)=>{const cv=v.nvd?.cvss||{},ep=safeNum(v.epss?.epss),epPct=(ep*100).toFixed(1),sev=String(cv.severity||'UNKNOWN').toUpperCase();return`<article class="vuln-watch-card" data-cve="${esc(v.id)}"><div class="vuln-watch-top"><span class="watch-index">${String(i+1).padStart(2,'0')}</span><span class="priority p-${v.priority.label.toLowerCase()}">${v.priority.label} · ${v.priority.score}</span></div><h3>${esc(v.id)}</h3><p>${esc(v.vendor)} · ${esc(v.product)}</p><div class="watch-metrics"><div><span>CVSS</span><strong>${cv.score==null?'—':safeNum(cv.score).toFixed(1)}</strong><small>${esc(sev)}</small></div><div><span>EPSS</span><strong>${v.epss?epPct+'%':'—'}</strong><small>${v.epss?`${(safeNum(v.epss.percentile)*100).toFixed(1)} pct`:'No score'}</small></div><div><span>Ransomware</span><strong class="${v.ransomware?'text-red':'text-green'}">${v.ransomware?'YES':'NO'}</strong><small>Known use</small></div></div><div class="watch-probability"><span>Exploit probability</span><div><i style="width:${Math.min(100,ep*100)}%"></i></div></div><div class="watch-footer"><span>Added ${esc(v.dateAdded||'—')}</span><a href="${esc(nvdUrl(v.id))}" target="_blank" rel="noopener">NVD ↗</a></div></article>`}).join('')||'<div class="empty-state">Waiting for correlated vulnerability intelligence.</div>';if($('vulnMomentumChart'))$('vulnMomentumChart').innerHTML=lineChartSvg(buildDailyKev(90));if($('vulnMomentumBadge'))$('vulnMomentumBadge').textContent=`${fmt(UNIFIED.filter(v=>ageDays(v.dateAdded)<=90).length)} KEV · 90D`}
function applyVulnPreset(preset){VULN_PRESET=preset||'all';$('search').value='';$('severityFilter').value='all';$('epssFilter').value='all';$('priorityFilter').value='all';$('ransomFilter').value='all';if(preset==='critical')$('priorityFilter').value='CRITICAL';if(preset==='epss50')$('epssFilter').value='50';if(preset==='ransomware')$('ransomFilter').value='yes';PAGE=1;document.querySelectorAll('[data-vuln-preset]').forEach(b=>b.classList.toggle('active',b.dataset.vulnPreset===VULN_PRESET));renderTable();if(preset!=='all')document.querySelector('.vuln-table-card')?.scrollIntoView({behavior:'smooth',block:'start'})}
function epssMatch(v,f){const p=v.epss?.epss;if(f==='all')return true;if(p==null)return false;return f==='50'?p>=.5:f==='10'?p>=.1:f==='1'?p>=.01:f==='lt1'?p<.01:true}
function filteredVulns(){const q=$('search').value.trim().toLowerCase(),sev=$('severityFilter').value,ep=$('epssFilter').value,pri=$('priorityFilter').value,ran=$('ransomFilter').value;return UNIFIED.filter(v=>{const s=String(v.nvd?.cvss?.severity||'UNKNOWN').toUpperCase(),hay=`${v.id} ${v.vendor} ${v.product} ${v.vulnerabilityName} ${v.nvd?.description||''}`.toLowerCase(),presetOk=VULN_PRESET!=='new7'||ageDays(v.dateAdded)<=7;return presetOk&&(!q||hay.includes(q))&&(sev==='all'||s===sev)&&epssMatch(v,ep)&&(pri==='all'||v.priority.label===pri)&&(ran==='all'||(ran==='yes'?v.ransomware:!v.ransomware))})}
function renderTable(){const items=filteredVulns(),pages=Math.max(1,Math.ceil(items.length/PAGE_SIZE));PAGE=Math.min(PAGE,pages);const slice=items.slice((PAGE-1)*PAGE_SIZE,PAGE*PAGE_SIZE);$('resultLabel').textContent=`${fmt(items.length)} matching records · 50 per page`;$('pageLabel').textContent=`Page ${PAGE} of ${pages}`;$('prevPage').disabled=PAGE<=1;$('nextPage').disabled=PAGE>=pages;$('rows').innerHTML=slice.map(v=>{const cv=v.nvd?.cvss||{},sev=String(cv.severity||'UNKNOWN').toUpperCase(),ep=v.epss?`${(safeNum(v.epss.epss)*100).toFixed(2)}%`:'—';return`<tr data-cve="${esc(v.id)}"><td><a class="cve-link" href="${esc(nvdUrl(v.id))}" target="_blank" rel="noopener">${esc(v.id)} ↗</a><span class="cell-sub">Added ${esc(v.dateAdded||'—')}</span></td><td><strong>${esc(v.vendor)}</strong><span class="cell-sub">${esc(v.product)}</span></td><td><strong>${cv.score==null?'—':safeNum(cv.score).toFixed(1)}</strong> <span class="sev-badge sev-${sev.toLowerCase()}">${esc(sev)}</span></td><td><strong>${ep}</strong><span class="cell-sub">${v.epss?`${(safeNum(v.epss.percentile)*100).toFixed(1)} percentile`:''}</span></td><td><span class="pill ${v.ransomware?'pill-red':'pill-green'}">${v.ransomware?'KNOWN':'NOT KNOWN'}</span></td><td><span class="priority p-${v.priority.label.toLowerCase()}">${v.priority.label}</span><span class="cell-sub">${v.priority.score}/100</span></td><td><strong>${esc(v.vulnerabilityName)}</strong><span class="cell-sub">${esc(v.nvd?.description||v.description||'')}</span></td><td><div class="evidence-links"><a href="${esc(nvdUrl(v.id))}" target="_blank" rel="noopener">NVD</a><a href="${esc(cisaCveUrl(v.id))}" target="_blank" rel="noopener">CISA</a><a href="${esc(epssUrl(v.id))}" target="_blank" rel="noopener">EPSS</a></div></td></tr>`}).join('')||'<tr><td colspan="8" class="empty-state">No records match your filters.</td></tr>'}
function ransomwareCountryUrl(code){return `https://www.ransomware.live/map/${encodeURIComponent(code)}`}
function openAseanDrawer(code){const member=ASEAN_MEMBERS.find(m=>m.code===code);if(!member)return;const r=regionalData();const claims=r.asean.filter(v=>v._member?.code===code).sort((a,b)=>dateMs(b.discovered)-dateMs(a.discovered));const d30=claims.filter(v=>withinDays(v.discovered,30)).length,d90=claims.filter(v=>withinDays(v.discovered,90)).length,groups=countBy(claims,v=>v.group||'Unknown'),sectors=countBy(claims,v=>v.sector||'Unspecified'),src=ransomwareCountryUrl(code);const rows=claims.slice(0,60).map(v=>`<div class="country-claim"><div><strong>${esc(v.victim||'Unknown victim')}</strong><small>${esc(v.group||'Unknown group')} · ${esc(v.sector||'Unspecified sector')}</small></div><time>${esc(v.discovered?fmtDate(v.discovered):'Unknown date')}</time></div>`).join('')||'<div class="empty-state">No retained claims for this country yet. The rolling archive begins from the time this patch is installed.</div>';$('drawerContent').innerHTML=`<span class="drawer-kicker">ASEAN RANSOMWARE INTELLIGENCE</span><h2 class="drawer-title">${member.flag} ${esc(member.name)}</h2><p class="drawer-sub">Public ransomware/extortion victim claims · rolling retained history</p><div class="drawer-score-grid"><div><span>Retained claims</span><strong>${fmt(claims.length)}</strong></div><div><span>≤30 days</span><strong>${fmt(d30)}</strong></div><div><span>≤90 days</span><strong>${fmt(d90)}</strong></div></div><div class="drawer-section drawer-meta"><h4>Regional profile</h4><div><span>Top ransomware group</span><strong>${esc(groups[0]?.name||'—')}</strong></div><div><span>Top targeted sector</span><strong>${esc(sectors[0]?.name||'—')}</strong></div><div><span>History source</span><strong>${sourceReady(RWHIST)?'Rolling archive':'Latest 100 feed'}</strong></div></div><div class="drawer-section"><h4>Retained victim claims</h4><div class="country-claim-list">${rows}</div></div><div class="drawer-links"><a href="${esc(src)}" target="_blank" rel="noopener">Open ransomware.live country view ↗</a><a href="${esc(ransomwareSourceUrl())}" target="_blank" rel="noopener">Open source platform ↗</a></div><div class="drawer-note">Claims are OSINT disclosures from ransomware/extortion leak sites and are not independently verified incidents. The Phase 1 rolling archive accumulates new records from the public recent-victims feed over time.</div>`;$('detailDrawer').classList.add('open');$('drawerBackdrop').classList.add('open');$('detailDrawer').setAttribute('aria-hidden','false')}
function openCveDrawer(id){const v=UNIFIED.find(x=>x.id===id);if(!v)return;const cv=v.nvd?.cvss||{},epss=v.epss?`${(safeNum(v.epss.epss)*100).toFixed(2)}%`:'—',events=[];const push=(date,title,text,tone='cyan')=>{if(date&&dateMs(date))events.push({date,title,text,tone,ms:dateMs(date)})};push(v.nvd?.published||v.nvd?.publishedAt,'NVD published','Initial vulnerability record','blue');push(v.dateAdded,'Added to CISA KEV','Confirmed known exploitation','red');push(EPSS?.meta?.scoreDate,'FIRST EPSS score',v.epss?`${(safeNum(v.epss.epss)*100).toFixed(2)}% exploitation probability`:'No matched EPSS score','amber');push(v.nvd?.lastModified,'NVD last modified','Latest NVD metadata update','cyan');push(v.dueDate,'CISA remediation due','Required-action due date','green');events.sort((a,b)=>a.ms-b.ms);const timeline=events.length?events.map(e=>`<div class="evidence-event ${e.tone}"><i></i><div><time>${esc(new Date(e.ms).toLocaleDateString())}</time><strong>${esc(e.title)}</strong><span>${esc(e.text)}</span></div></div>`).join(''):'<div class="empty-state">Timeline metadata not available.</div>';$('drawerContent').innerHTML=`<span class="drawer-kicker">CORRELATED VULNERABILITY INTELLIGENCE</span><div class="drawer-title-row"><div><h2 class="drawer-title">${esc(v.id)}</h2><p class="drawer-sub">${esc(v.vendor)} · ${esc(v.product)}</p></div><span class="priority p-${v.priority.label.toLowerCase()}">${v.priority.label} · CTI ${v.priority.score}/100</span></div><div class="drawer-score-grid four"><div><span>CVSS</span><strong>${cv.score==null?'—':safeNum(cv.score).toFixed(1)}</strong><small>${esc(cv.severity||'UNKNOWN')}</small></div><div><span>EPSS</span><strong>${epss}</strong><small>${v.epss?`${(safeNum(v.epss.percentile)*100).toFixed(1)} percentile`:'No score'}</small></div><div><span>CISA KEV</span><strong>YES</strong><small>Known exploited</small></div><div><span>Ransomware</span><strong class="${v.ransomware?'text-red':'text-green'}">${v.ransomware?'KNOWN':'NOT KNOWN'}</strong><small>Campaign use</small></div></div><div class="drawer-section signal-meter-section"><div class="signal-meter-head"><h4>CTI priority signal</h4><strong>${v.priority.score}/100</strong></div><div class="signal-meter"><i style="width:${v.priority.score}%"></i></div><p>External-intelligence priority combining severity, exploit probability, known ransomware use and KEV recency.</p></div><div class="drawer-section"><h4>Vulnerability</h4><p>${esc(v.vulnerabilityName||v.nvd?.description||v.description||'No description available.')}</p></div><div class="drawer-section"><h4>NVD description</h4><p>${esc(v.nvd?.description||'No NVD description available.')}</p></div><div class="drawer-section action-section"><h4>CISA required action</h4><p>${esc(v.requiredAction||'No action text available.')}</p></div><div class="drawer-section"><h4>Evidence timeline</h4><div class="evidence-timeline">${timeline}</div></div><div class="drawer-section drawer-meta"><h4>Technical evidence</h4><div><span>Date added to KEV</span><strong>${esc(v.dateAdded||'—')}</strong></div><div><span>CISA due date</span><strong>${esc(v.dueDate||'—')}</strong></div><div><span>CVSS vector</span><strong>${esc(cv.vector||'—')}</strong></div><div><span>EPSS percentile</span><strong>${v.epss?`${(safeNum(v.epss.percentile)*100).toFixed(1)}%`:'—'}</strong></div></div><div class="drawer-links evidence-source-links"><a href="${esc(nvdUrl(v.id))}" target="_blank" rel="noopener">Open NVD record ↗</a><a href="${esc(cisaCveUrl(v.id))}" target="_blank" rel="noopener">Find in CISA KEV ↗</a><a href="${esc(epssUrl(v.id))}" target="_blank" rel="noopener">Open FIRST EPSS data ↗</a></div><div class="drawer-note">CTI Priority is a dashboard-derived external intelligence score. It is not organisational risk until asset exposure and business criticality are correlated.</div>`;$('detailDrawer').classList.add('open');$('drawerBackdrop').classList.add('open');$('detailDrawer').setAttribute('aria-hidden','false')}
function closeDrawer(){$('detailDrawer').classList.remove('open');$('drawerBackdrop').classList.remove('open');$('detailDrawer').setAttribute('aria-hidden','true')}

function renderBriefing(){const p=posture(),reg=regionalData(),events=buildEvents(),sources=sourceStates(),top=topKevs(5),healthy=sources.filter(x=>x.ready&&!x.degraded).length,degraded=sources.filter(x=>x.degraded).length,offline=sources.filter(x=>!x.ready).length,confidence=offline>=2?'LIMITED':degraded||offline?'MODERATE':'HIGH',latest=events[0],topGroup=(RW?.topGroups||[])[0]||reg.topGroup,latestMy=MYCERT?.advisories?.[0];$('briefHeadline').textContent=`${p.label} external threat posture · ${fmt(p.critical)} critical-priority KEVs`;$('briefGeneratedAt').textContent=`Generated ${new Date().toLocaleString()}`;$('briefWindow').textContent=latest?`Latest signal: ${eventTime(latest)}`:'Current window';$('briefConfidence').textContent=`Confidence ${confidence}`;$('briefSummary').textContent=`Current external intelligence shows ${fmt(p.critical)} known exploited vulnerabilities at Critical CTI priority. ${fmt(p.epssHigh)} KEVs have EPSS ≥50%, while the loaded ransomware feed contains ${fmt(p.rw24)} claims discovered within 24 hours. Malaysia has ${fmt(reg.malaysia.filter(v=>withinDays(v.discovered,30)).length)} loaded claims within 30 days.`;const pri=[{tone:'critical',n:'01',t:'Exploit-priority vulnerabilities',v:fmt(p.critical),txt:top[0]?`${top[0].id} leads the watchlist at ${top[0].priority.score}/100${top[0].ransomware?', with known ransomware use':''}.`:'Waiting for correlated KEV intelligence.'},{tone:'ransomware',n:'02',t:'Ransomware activity',v:fmt(p.rw24),txt:topGroup?`${topGroup.name||'Unknown'} is the leading group in the currently loaded ranking.`:'Waiting for ransomware intelligence.'},{tone:'regional',n:'03',t:'Malaysia / ASEAN watch',v:fmt(reg.malaysia.filter(v=>withinDays(v.discovered,30)).length),txt:latestMy?`Latest MyCERT signal: ${latestMy.title}.`:'MyCERT collection pending.'}];$('briefPriorities').innerHTML=pri.map(x=>`<div class="brief-priority"><span class="brief-num">${x.n}</span><div><span>${esc(x.t)}</span><strong>${esc(x.v)}</strong><p>${esc(x.txt)}</p></div></div>`).join('');$('briefChanges').innerHTML=events.slice(0,5).map(e=>`<div class="brief-list-item"><i class="brief-dot sev-${e.severity}"></i><div><strong>${esc(e.title)}</strong><small>${esc(e.source)} · ${esc(eventTime(e))}</small></div></div>`).join('');const watch=[];if(top[0])watch.push(`${top[0].id}: CTI ${top[0].priority.score}/100${top[0].epss?`, EPSS ${(safeNum(top[0].epss.epss)*100).toFixed(1)}%`:''}.`);if(topGroup)watch.push(`Monitor ${topGroup.name||'leading ransomware group'} activity and changes in country/sector targeting.`);if(latestMy)watch.push(`Review MyCERT: ${latestMy.title}.`);if(degraded)watch.push(`Collection assurance: ${sources.filter(x=>x.degraded).map(x=>x.name).join(', ')} is degraded; last good data is retained.`);else if(offline)watch.push(`Restore unavailable source: ${sources.filter(x=>!x.ready).map(x=>x.name).join(', ')}.`);else watch.push('All collection sources are healthy; continue automated monitoring.');$('briefWatch').innerHTML=watch.map((x,i)=>`<div class="brief-list-item"><span class="brief-num">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(x)}</strong></div></div>`).join('');$('executiveWatchlist').innerHTML=top.map((v,i)=>`<div class="watchlist-row" data-cve="${esc(v.id)}"><span class="watch-rank">${String(i+1).padStart(2,'0')}</span><div class="watch-main"><div><strong>${esc(v.id)}</strong><span class="priority p-${v.priority.label.toLowerCase()}">${v.priority.label}</span></div><small>${esc(v.vendor)} · ${esc(v.product)}</small><div class="watch-metrics"><span>CTI <b>${v.priority.score}</b></span><span>CVSS <b>${v.nvd?.cvss?.score??'—'}</b></span><span>EPSS <b>${v.epss?`${(safeNum(v.epss.epss)*100).toFixed(1)}%`:'—'}</b></span>${v.ransomware?'<span class="rw-flag">RANSOMWARE</span>':''}</div></div></div>`).join('');$('regionalBrief').innerHTML=`<div class="regional-kpis"><div><span>Malaysia ≤30d</span><strong>${fmt(reg.malaysia.filter(v=>withinDays(v.discovered,30)).length)}</strong></div><div><span>ASEAN loaded</span><strong>${fmt(reg.asean.length)}</strong></div><div><span>ASEAN ≤24h</span><strong>${fmt(reg.asean.filter(v=>withinDays(v.discovered,1)).length)}</strong></div><div><span>Top country</span><strong>${esc(reg.topCountry?.count?reg.topCountry.member.name:'—')}</strong></div></div>`;$('briefSourceState').textContent=offline?`${healthy} healthy · ${offline} unavailable`:degraded?`${healthy} live · ${degraded} degraded`:`${healthy} / 5 healthy`;$('briefSourceHealth').innerHTML=sources.map(s=>`<div class="brief-source-row"><span class="brief-source-code">${esc(s.code)}</span><div><strong>${esc(s.name)}</strong><small>${esc(s.collected?relTime(s.collected):'Not collected')}</small></div><b class="brief-source-state ${!s.ready?'offline':s.degraded?'degraded':''}">${!s.ready?'OFFLINE':s.degraded?'DEGRADED':'LIVE'}</b></div>`).join('')}
function briefText(){const p=posture(),reg=regionalData(),sources=sourceStates(),top=topKevs(3),events=buildEvents().slice(0,4);return['CYBER THREAT INTELLIGENCE — EXECUTIVE BRIEF',`Generated: ${new Date().toLocaleString()}`,'',`Posture: ${p.label} (${p.score}/100)`,`Critical-priority KEVs: ${p.critical}`,`KEVs EPSS ≥50%: ${p.epssHigh}`,`Ransomware claims ≤24h: ${p.rw24}`,`Malaysia claims ≤30d: ${reg.malaysia.filter(v=>withinDays(v.discovered,30)).length}`,'','TOP WATCHLIST',...top.map((v,i)=>`${i+1}. ${v.id} — CTI ${v.priority.score}; CVSS ${v.nvd?.cvss?.score??'—'}; EPSS ${v.epss?`${(safeNum(v.epss.epss)*100).toFixed(1)}%`:'—'}; ransomware ${v.ransomware?'known':'not known'}`),'','LATEST SIGNALS',...events.map((e,i)=>`${i+1}. ${e.source}: ${e.title} (${eventTime(e)})`),'','SOURCE HEALTH',...sources.map(s=>`${s.name}: ${!s.ready?'OFFLINE':s.degraded?'DEGRADED':'LIVE'}`)].join('\n')}

function renderSources(){$('sourceCards').innerHTML=sourceStates().map(s=>`<article class="source-card"><span class="source-state ${!s.ready?'offline':s.degraded?'warn':''}">${!s.ready?'OFFLINE':s.degraded?'DEGRADED':'LIVE'}</span><span class="source-code">${esc(s.code)}</span><h3>${esc(s.name)}</h3><p>${esc(s.desc)}</p><div class="source-meta"><span>Collected: ${esc(s.collected?fmtDate(s.collected):'Not collected')}</span><span>Age: ${esc(s.collected?relTime(s.collected):'—')}</span></div><a href="${esc(s.url)}" target="_blank" rel="noopener">Open authoritative source ↗</a></article>`).join('')}


/* Phase 1H.2 — Global ransomware map + explorer */
let COUNTRY_META=null,WORLD_SVG='',COUNTRY_ALIAS=new Map(),RW_WINDOW='1';
const countryAliasKey=v=>String(v||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,' ').trim();
function initCountryAlias(){COUNTRY_ALIAS=new Map();for(const c of COUNTRY_META?.countries||[]){const vals=[c.name,c.alpha2,c.alpha3,...(c.aliases||[])];for(const a of vals){const k=countryAliasKey(a);if(k)COUNTRY_ALIAS.set(k,c)}}const extras={'usa':'United States','us':'United States','u s':'United States','united states of america':'United States','uk':'United Kingdom','u k':'United Kingdom','great britain':'United Kingdom','russia':'Russian Federation','viet nam':'Vietnam','south korea':'South Korea','republic of korea':'South Korea','korea south':'South Korea','north korea':'North Korea','czechia':'Czech Republic','lao pdr':'Laos','lao peoples democratic republic':'Laos','brunei darussalam':'Brunei','timor leste':'East Timor','east timor':'East Timor'};for(const[k,n]of Object.entries(extras)){const c=[...(COUNTRY_META?.countries||[])].find(x=>countryAliasKey(x.name)===countryAliasKey(n));if(c)COUNTRY_ALIAS.set(k,c)}}
function countryInfo(raw){const k=countryAliasKey(raw);if(!k)return null;return COUNTRY_ALIAS.get(k)||null}
function ransomwareBaseVictims(){const m=new Map();const put=v=>{if(!v)return;const key=String(v.id||`${v.victim||''}|${v.group||''}|${v.discovered||''}|${v.country||''}`);if(key)m.set(key,v)};if(sourceReady(RWHIST))for(const v of RWHIST.victims||[])put(v);if(sourceReady(RW))for(const v of RW.victims||[])put(v);return[...m.values()]}
function ransomwareVictimsSorted(){return ransomwareBaseVictims().slice().filter(v=>dateMs(v.discovered)).sort((a,b)=>dateMs(b.discovered)-dateMs(a.discovered))}
function ransomwareLiveVictims(){return ransomwareVictimsSorted().filter(v=>withinDays(v.discovered,1))}
function claimAgeHours(v){const t=dateMs(v?.discovered);return t?Math.max(0,(Date.now()-t)/3600000):Infinity}
function claimAgeClass(v){const h=claimAgeHours(v);return h<1?'now':h<6?'recent':h<=24?'day':'stale'}
function latestClaim(){return ransomwareVictimsSorted()[0]||null}
function renderRansomwareLivePulse(){const live=ransomwareLiveVictims(),latest=latestClaim(),countries=rwCountryRows(live).rows,groups=rwGroupRows(live),my=live.filter(v=>countryInfo(v.country)?.alpha2==='MY');if($('rwPulseLatest'))$('rwPulseLatest').textContent=latest?relTime(latest.discovered):'No dated claim';if($('rwPulseLatestMeta'))$('rwPulseLatestMeta').textContent=latest?`${latest.victim||'Unknown victim'} · ${latest.group||'Unknown group'} · ${countryInfo(latest.country)?.name||latest.country||'Unknown country'}`:'Waiting for source data';if($('rwPulse24'))$('rwPulse24').textContent=fmt(live.length);if($('rwPulseCountries'))$('rwPulseCountries').textContent=fmt(countries.length);if($('rwPulseGroups'))$('rwPulseGroups').textContent=fmt(groups.length);if($('rwPulseMalaysia'))$('rwPulseMalaysia').textContent=fmt(my.length);renderMapLiveClaims(live,latest)}
function renderMapLiveClaims(live,latest){const list=live.length?live:(latest?[latest]:[]),host=$('rwMapLiveClaims');if(!host)return;host.innerHTML=list.slice(0,12).map((v,i)=>{const c=countryInfo(v.country),age=claimAgeClass(v),fallback=!live.length;return`<button class="rw-live-claim age-${age}" type="button" data-rw-claim="${esc(v.id||'')}"><span class="claim-age-dot"></span><div><strong>${esc(v.victim||'Unknown victim')}</strong><small>${esc(v.group||'Unknown group')} · ${esc(c?.name||v.country||'Unknown')}</small><em>${fallback?'Latest known claim · ':''}${esc(relTime(v.discovered))}</em></div><span class="rw-live-arrow">↗</span></button>`}).join('')||'<div class="empty-state">No timestamped ransomware claims available.</div>'}
function rwWindowDays(){return RW_WINDOW==='all'?null:safeNum(RW_WINDOW,90)}
function rwWindowLabel(){if(RW_WINDOW==='1')return'LIVE · last 24 hours';if(RW_WINDOW==='7')return'last 7 days';return RW_WINDOW==='all'?(RWHIST?.meta?.fullSync?'full historical archive':'retained archive'):`last ${RW_WINDOW} days`}
function rwVictims(windowValue=RW_WINDOW){const base=ransomwareBaseVictims();if(windowValue==='all'||windowValue==null)return base.slice();const days=safeNum(windowValue,90);return base.filter(v=>withinDays(v.discovered,days))}
function rwCountryRows(victims){const m=new Map(),unmapped=[];for(const v of victims){const c=countryInfo(v.country);if(!c){unmapped.push(v);continue}const x=m.get(c.key)||{key:c.key,name:c.name,alpha2:c.alpha2,alpha3:c.alpha3,count:0};x.count++;m.set(c.key,x)}return{rows:[...m.values()].sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name)),unmapped}}
function rwGroupRows(victims){return countBy(victims,v=>v.group||'Unknown')}
function rwSectorRows(victims){return countBy(victims,v=>v.sector||'Unspecified')}
function rwSeries(victims,windowValue=RW_WINDOW){let days=windowValue==='all'?365:safeNum(windowValue,90);days=Math.max(7,Math.min(365,days));const bucket=days>120?7:1,buckets=[];const start=new Date();start.setUTCHours(0,0,0,0);start.setUTCDate(start.getUTCDate()-days+1);for(let i=0;i<days;i+=bucket){const d=new Date(start);d.setUTCDate(start.getUTCDate()+i);buckets.push({date:d.toISOString().slice(0,10),total:0,rw:0,start:d.getTime(),end:d.getTime()+bucket*86400000})}for(const v of victims){const t=dateMs(v.discovered);if(!t)continue;const b=buckets.find(x=>t>=x.start&&t<x.end);if(b)b.total++}return buckets.length?buckets:[{date:new Date().toISOString().slice(0,10),total:0,rw:0}]}
function trustedRansomUrl(v){try{const u=new URL(v||'');if(!/^https?:$/.test(u.protocol))return ransomwareSourceUrl();const h=u.hostname.toLowerCase();if(h==='ransomware.live'||h.endsWith('.ransomware.live')||h==='ransomwhere.org'||h.endsWith('.ransomwhere.org'))return u.href;return ransomwareSourceUrl()}catch{return ransomwareSourceUrl()}}
function ransomwareCountryUrl2(info){return info?.alpha2?`https://www.ransomware.live/map/${encodeURIComponent(info.alpha2)}`:ransomwareSourceUrl()}
function openDrawerHtml(html){$('drawerContent').innerHTML=html;$('detailDrawer').classList.add('open');$('drawerBackdrop').classList.add('open');$('detailDrawer').setAttribute('aria-hidden','false')}
function renderRansomwareActivity(target,victims){const data=rwSeries(victims);$(target).innerHTML=lineChartSvg(data);const half=Math.max(1,Math.floor(data.length/2)),a=data.slice(0,half).reduce((n,x)=>n+x.total,0),b=data.slice(half).reduce((n,x)=>n+x.total,0),label=b>a*1.12?'RISING':b<a*.88?'EASING':'STEADY';if($('rwTrendLabel2'))$('rwTrendLabel2').textContent=label;if($('rwActivityHint'))$('rwActivityHint').textContent=`${rwWindowLabel()} · ${(RW_WINDOW==='all'||safeNum(RW_WINDOW)>120)?'weekly':'daily'} buckets`}
