document.addEventListener('click',e=>{const w=e.target.closest('[data-rw-window]');if(w){RW_WINDOW=w.dataset.rwWindow;renderRansomware();return}const c=e.target.closest('[data-country-key]');if(c){openCountryDrawer(c.dataset.countryKey);return}const g=e.target.closest('[data-rw-group]');if(g){openGroupDrawer(g.dataset.rwGroup);return}const v=e.target.closest('[data-rw-claim]');if(v){openVictimDrawer(v.dataset.rwClaim);return}});

async function fetchJson(path){const r=await fetch(`${path}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`${path}: HTTP ${r.status}`);return r.json()}
async function fetchText(path){const r=await fetch(`${path}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`${path}: HTTP ${r.status}`);return r.text()}
async function refreshRansomwareFast({announce=true}={}){
  if(RW_FAST_POLLING)return;RW_FAST_POLLING=true;
  try{
    const next=await fetchJson('data/ransomware.json');
    if(!sourceReady(next))return;
    const nextIds=new Set((next.victims||[]).map(v=>String(v.id||'')).filter(Boolean));
    const previous=RW_SEEN_RECENT_IDS;
    RW_NEW_IDS=new Set();
    if(previous){for(const id of nextIds)if(!previous.has(id))RW_NEW_IDS.add(id)}
    const changed=(next?.meta?.collectedAt||'')!==(RW?.meta?.collectedAt||'')||RW_NEW_IDS.size>0;
    RW=next;RW_SEEN_RECENT_IDS=nextIds;
    if(changed){
      renderHeader();renderPosture();renderTopThree();renderRansomware();renderOverviewAsean();renderOverviewFeed();renderThreadHubOverview();renderRegional();renderUnifiedFeed();renderBriefing();renderSources();
      if(announce&&RW_NEW_IDS.size){const latest=(next.victims||[]).filter(v=>RW_NEW_IDS.has(String(v.id||''))).sort((a,b)=>dateMs(b.discovered)-dateMs(a.discovered))[0];if(latest)toast(`New ransomware claim: ${latest.victim||'Unknown'} · ${latest.group||'Unknown group'}`)}
      const sync=document.getElementById('rwBrowserSync');if(sync){sync.textContent=`AUTO SYNC · ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;sync.classList.add('flash');setTimeout(()=>sync.classList.remove('flash'),900)}
      setTimeout(()=>{RW_NEW_IDS=new Set();renderRansomware()},4500);
    }else{const sync=document.getElementById('rwBrowserSync');if(sync)sync.textContent=`AUTO SYNC · checked ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`}
  }catch(err){const sync=document.getElementById('rwBrowserSync');if(sync)sync.textContent='AUTO SYNC · retrying';console.warn('Ransomware fast poll failed',err)}finally{RW_FAST_POLLING=false}
}
function startRansomwareAutoSync(){
  clearInterval(RW_FAST_TIMER);RW_FAST_TIMER=setInterval(()=>refreshRansomwareFast(),60*1000);
  window.addEventListener('focus',()=>refreshRansomwareFast({announce:false}));
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshRansomwareFast({announce:false})});
}

async function load(){const paths=['data/kev.json','data/nvd.json','data/epss.json','data/ransomware.json','data/ransomware-history.json','data/mycert.json','data/country-meta.json'];const [res,mapRes]=await Promise.all([Promise.allSettled(paths.map(fetchJson)),Promise.resolve(WORLD_SVG||'').then(async cached=>cached||await fetchText('assets/world-map.svg')).then(v=>({status:'fulfilled',value:v})).catch(reason=>({status:'rejected',reason}))]);[KEV,NVD,EPSS,RW,RWHIST,MYCERT,COUNTRY_META]=res.map(x=>x.status==='fulfilled'?x.value:null);if(mapRes.status==='fulfilled')WORLD_SVG=mapRes.value;initCountryAlias();NVD_BY_ID=sourceReady(NVD)?new Map((NVD.vulnerabilities||[]).map(v=>[v.id,v])):new Map();EPSS_BY_ID=sourceReady(EPSS)?new Map((EPSS.vulnerabilities||[]).map(v=>[v.id,v])):new Map();UNIFIED=buildUnified();if(!RW_SEEN_RECENT_IDS&&sourceReady(RW))RW_SEEN_RECENT_IDS=new Set((RW.victims||[]).map(v=>String(v.id||'')).filter(Boolean));renderHeader();renderPosture();renderTopThree();renderKevTrend();renderRiskScatter('riskScatter');renderRiskScatter('riskScatterFull');renderRansomware();renderOverviewAsean();renderOverviewFeed();renderThreadHubOverview();renderRegional();renderSeverityAndEpss();renderVulnerabilityCommand();renderVendors();renderTable();renderUnifiedFeed();renderBriefing();renderSources()}

document.addEventListener('click',e=>{const p=e.target.closest('[data-vuln-preset]');if(p){applyVulnPreset(p.dataset.vulnPreset);return}const v=e.target.closest('[data-vendor-search]');if(v){VULN_PRESET='all';$('search').value=v.dataset.vendorSearch||'';$('severityFilter').value='all';$('epssFilter').value='all';$('priorityFilter').value='all';$('ransomFilter').value='all';PAGE=1;document.querySelectorAll('[data-vuln-preset]').forEach(b=>b.classList.toggle('active',b.dataset.vulnPreset==='all'));renderTable();document.querySelector('.vuln-table-card')?.scrollIntoView({behavior:'smooth',block:'start'});}});
['search','severityFilter','epssFilter','priorityFilter','ransomFilter'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',()=>{VULN_PRESET='all';PAGE=1;document.querySelectorAll('[data-vuln-preset]').forEach(b=>b.classList.toggle('active',b.dataset.vulnPreset==='all'));renderTable()}));
$('prevPage').addEventListener('click',()=>{if(PAGE>1){PAGE--;renderTable()}});$('nextPage').addEventListener('click',()=>{PAGE++;renderTable()});
$('feedFilters').addEventListener('click',e=>{const b=e.target.closest('[data-feed-filter]');if(!b)return;FEED_FILTER=b.dataset.feedFilter;FEED_LIMIT=24;document.querySelectorAll('#feedFilters button').forEach(x=>x.classList.toggle('active',x===b));renderUnifiedFeed()});$('feedMore').addEventListener('click',()=>{FEED_LIMIT+=24;renderUnifiedFeed()});
$('drawerClose').addEventListener('click',closeDrawer);$('drawerBackdrop').addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});
$('copyBrief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(briefText());toast('Executive brief copied')}catch{toast('Clipboard unavailable')}});$('printBrief').addEventListener('click',()=>window.print());
function runGlobalSearch(){const el=$('globalSearch'),q=el?.value.trim();if(!q)return;const upper=q.toUpperCase();if(/^CVE-\d{4}-\d+$/i.test(q)){switchTab('vulnerabilities');$('search').value=upper;VULN_PRESET='all';PAGE=1;renderTable();setTimeout(()=>document.querySelector('.vuln-table-card')?.scrollIntoView({behavior:'smooth',block:'start'}),220);return}const victims=ransomwareBaseVictims(),victim=victims.find(v=>`${v.victim||''} ${v.website||''}`.toLowerCase().includes(q.toLowerCase()));if(victim){switchTab('ransomware');setTimeout(()=>openVictimDrawer(victim.id),180);return}const group=rwGroupRows(victims).find(x=>x.name.toLowerCase().includes(q.toLowerCase()));if(group){switchTab('ransomware');setTimeout(()=>openGroupDrawer(group.name),180);return}const country=countryInfo(q);if(country){switchTab('ransomware');setTimeout(()=>openCountryDrawer(country.key),180);return}switchTab('vulnerabilities');$('search').value=q;VULN_PRESET='all';PAGE=1;renderTable();toast(`Searching loaded intelligence for “${q}”`)}
if($('globalSearch'))$('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();runGlobalSearch()}});
const initial=location.hash.replace('#','');if(['overview','briefing','regional','ransomware','vulnerabilities','live','sources'].includes(initial))switchTab(initial);
load().then(()=>startRansomwareAutoSync());setInterval(load,5*60*1000);
